        progress("checking independent glass controls");int wallpaper=store.prefs.getInt("wallpaper",0);setting("Window Color");click("@control","Glass color: Lavender");check(store.prefs.getInt("aero_color",-1)==4&&store.prefs.getInt("wallpaper",0)==wallpaper,"Glass color does not change wallpaper");
